css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader .bell { position: relative; width: 46%; height: 34%; background: radial-gradient(circle at 45% 32%, color-mix(in srgb, #fff 45%, var(--accent)), var(--accent) 68%, var(--accent-2)); border-radius: 50% 50% 32% 32%; box-shadow: 0 0 calc(var(--loader-size) * .16) color-mix(in srgb, var(--accent) 45%, transparent); animation: jelly-pulse calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader .bell::after { content: ''; position: absolute; top: 88%; left: 6%; width: 88%; height: 130%; background: repeating-linear-gradient(90deg, var(--accent) 0 9%, transparent 9% 20%); -webkit-mask: linear-gradient(#000, transparent 88%); mask: linear-gradient(#000, transparent 88%); border-radius: 0 0 40% 40%; transform-origin: 50% 0; animation: jelly-sway calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
@keyframes jelly-pulse { 0%, 100% { transform: scale(1, 1); } 50% { transform: scale(1.08, .82); } }
@keyframes jelly-sway { 0%, 100% { transform: skewX(7deg); } 50% { transform: skewX(-7deg); } }
